<?php
require_once __DIR__ . '/config.php'; require_login(); $pdo=db(); $stages=stages();
$jobId=(int)($_GET['job_id']??$_POST['job_id']??0); $stage=$_GET['stage']??$_POST['stage']??'';
if(!isset($stages[$stage])) { flash('Invalid production stage.','error'); redirect('dashboard.php'); }
if(!is_admin() && current_user()['assigned_stage']!==$stage) { http_response_code(403); exit('This job stage is not assigned to your account.'); }
$s=$pdo->prepare("SELECT j.*,u.status,u.completed_quantity,u.note AS stage_note,u.employee_id,u.updated_at AS stage_updated FROM production_jobs j JOIN production_updates u ON u.job_id=j.id AND u.stage=? WHERE j.id=?");
$s->execute([$stage,$jobId]); $row=$s->fetch(); if(!$row){flash('Production job not found.','error');redirect('dashboard.php');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $status=$_POST['status']??'pending'; $qty=filter_var($_POST['completed_quantity']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]); $note=trim($_POST['note']??'');
    if(!in_array($status,['pending','in_progress','completed'],true) || $qty===false) $error='Please check the status and completed quantity.';
    elseif($qty>(int)$row['total_quantity']) $error='Completed quantity cannot be greater than the order quantity.';
    elseif($status==='completed' && $qty<(int)$row['total_quantity']) $error='To mark this stage completed, completed quantity must equal the order quantity. If not all copies are ready, choose In progress.';
    else {
        $employeeId=current_user()['id'];
        $s=$pdo->prepare("UPDATE production_updates SET status=?,completed_quantity=?,employee_id=?,note=?,updated_at=CURRENT_TIMESTAMP WHERE job_id=? AND stage=?");
        $s->execute([$status,$qty,$employeeId,$note?:null,$jobId,$stage]);
        $s=$pdo->prepare("INSERT INTO production_history (job_id,stage,status,completed_quantity,note,changed_by) VALUES (?,?,?,?,?,?)");
        $s->execute([$jobId,$stage,$status,$qty,$note?:null,$employeeId]);
        flash($stages[$stage]['label'].' status updated successfully.'); redirect('update.php?job_id='.$jobId.'&stage='.$stage);
    }
}
$s=$pdo->prepare("SELECT h.*,u.full_name FROM production_history h LEFT JOIN users u ON u.id=h.changed_by WHERE h.job_id=? AND h.stage=? ORDER BY h.changed_at DESC LIMIT 12");$s->execute([$jobId,$stage]);$history=$s->fetchAll();
$all=$pdo->prepare("SELECT u.*,usr.full_name FROM production_updates u LEFT JOIN users usr ON usr.id=u.employee_id WHERE u.job_id=? ORDER BY FIELD(u.stage,'printing','binding','cutting','lamination','packing')");$all->execute([$jobId]);$allRows=$all->fetchAll();
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Update <?=e($stages[$stage]['label'])?> | <?=e(APP_NAME)?></title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="side-brand" href="dashboard.php"><div class="brand-mark">BP</div><div><strong>BOOKPRINTERS</strong><small>& SHREEPUBLICATIONS</small></div></a><div class="side-label">WORKSPACE</div><a class="nav-link" href="dashboard.php"><span>▦</span> Overview</a><?php if(is_admin()): ?><a class="nav-link" href="jobs.php"><span>▤</span> Production jobs</a><a class="nav-link" href="employees.php"><span>♙</span> Employees & access</a><?php endif; ?><div class="sidebar-bottom"><div class="user-mini"><div class="avatar"><?=e(strtoupper(substr(current_user()['full_name'],0,1)))?></div><div><strong><?=e(current_user()['full_name'])?></strong><small><?=is_admin()?'Administrator':e($stages[current_user()['assigned_stage']]['label']??'Employee')?></small></div></div><a class="nav-link logout" href="logout.php"><span>↪</span> Sign out</a></div></aside><main class="main"><header class="topbar"><div><p class="eyebrow">PRODUCTION / UPDATE</p><h1>Update production stage</h1></div><a class="btn secondary" href="dashboard.php">← Dashboard</a></header><?php if($flash): ?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif; ?><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><section class="job-detail-head"><div class="book-cover-large">▤</div><div class="job-detail-title"><span class="status <?=e($row['priority'])?>"><?=e(ucfirst($row['priority']))?> priority</span><h2><?=e($row['book_title'])?></h2><p class="muted"><?=e($row['job_code'])?> · <?=number_format((int)$row['total_quantity'])?> copies<?= $row['client_name']?' · '.e($row['client_name']):'' ?></p><?php if($row['due_date']): ?><p class="small muted">Target date: <?=e($row['due_date'])?></p><?php endif; ?></div></section><section class="panel stage-panel"><div class="panel-heading"><div><p class="eyebrow">STAGE <?= $stages[$stage]['step'] ?> OF 5</p><h2><?=e($stages[$stage]['label'])?></h2><p class="muted small">Assigned employee: <?=e($stages[$stage]['employee'])?></p></div><span class="status <?=e($row['status'])?>"><?=e(stage_status_label($row['status']))?></span></div><div class="stage-route"><?php foreach($stages as $key=>$meta): ?><div class="route-stage <?=($key===$stage?'current ':'').(($allRows[array_search($key,array_column($allRows,'stage'))]['status']??'pending')==='completed'?'done':'')?>"><span><?=($allRows[array_search($key,array_column($allRows,'stage'))]['status']??'pending')==='completed'?'✓':$meta['step']?></span><small><?=e($meta['label'])?></small></div><?php if($meta['step']<5): ?><i>›</i><?php endif; ?><?php endforeach; ?></div><form method="post" class="job-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="job_id" value="<?=$jobId?>"><input type="hidden" name="stage" value="<?=e($stage)?>"><div class="form-grid"><div class="field"><label>Current status *</label><select name="status" required><option value="pending" <?=$row['status']==='pending'?'selected':''?>>Pending</option><option value="in_progress" <?=$row['status']==='in_progress'?'selected':''?>>In progress</option><option value="completed" <?=$row['status']==='completed'?'selected':''?>>Completed</option></select></div><div class="field"><label>Quantity completed (copies) *</label><input type="number" name="completed_quantity" min="0" max="<?=(int)$row['total_quantity']?>" required value="<?=e($row['completed_quantity'])?>"><small class="muted">Order quantity: <?=number_format((int)$row['total_quantity'])?> copies</small></div><div class="field wide"><label>Work note / issue (optional)</label><textarea name="note" rows="3" placeholder="e.g. 1200 copies complete; balance waiting for covers..."><?=e($row['stage_note']??'')?></textarea></div></div><div class="form-actions"><a class="btn secondary" href="dashboard.php">Cancel</a><button class="btn primary" type="submit">Save production update →</button></div></form></section><section class="panel"><div class="panel-heading"><div><h3>Update history</h3><p class="muted small">Record of changes made to this stage</p></div></div><?php if($history): ?><div class="activity-list"><?php foreach($history as $h): ?><div class="activity-item"><div class="activity-dot"></div><div class="activity-content"><strong><?=e(stage_status_label($h['status']))?> · <?=number_format((int)$h['completed_quantity'])?> copies</strong><span><?=e($h['full_name']??'Former user')?><?= $h['note']?' — '.e($h['note']):'' ?></span></div><time><?=e(date('d M, g:i A',strtotime($h['changed_at'])))?></time></div><?php endforeach; ?></div><?php else: ?><p class="muted empty-line">No changes recorded yet.</p><?php endif; ?></section><footer class="footer">© <?=date('Y')?> BookPrinters & ShreePublications <span>Production made visible.</span></footer></main></div></body></html>
